import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './css/HealthAssessment.css';

function HealthAssessment() {
  const navigate = useNavigate();
  const API_BASE_URL = 
    process.env.NODE_ENV === 'production'
      ? 'https://airaware-app-gcw7.onrender.com'
      : 'http://localhost:8000';

  // Get CSRF Token
  const getCsrfToken = () => {
    const cookies = document.cookie.split(';');
    for (let cookie of cookies) {
      const [name, value] = cookie.trim().split('=');
      if (name === 'csrftoken') {
        return decodeURIComponent(value);
      }
    }
    return null;
  };

  // Initial Form State
  const [formData, setFormData] = useState({
    age_group: '',
    gender: '',
    respiratory_conditions: [],
    smoking_history: '',
    living_environment: [],
    common_symptoms: [],
    occupational_exposure: '',
    medical_history: []
  });

  // State for form validation and submission
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState('');

  // Predefined Options
  const ageGroups = [
    '0-12 years', 
    '13-18 years', 
    '19-35 years', 
    '36-50 years', 
    '51-65 years', 
    '65+ years'
  ];

  const respiratoryConditions = [
    'Asthma', 
    'COPD', 
    'Bronchitis', 
    'None'
  ];

  const livingEnvironments = [
    'Urban', 
    'Suburban', 
    'Rural', 
    'Industrial Area'
  ];

  const commonSymptoms = [
    'Cough', 
    'Shortness of Breath', 
    'Wheezing', 
    'Chest Pain', 
    'None'
  ];

  // Form Change Handler
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    // Handle checkbox groups
    if (type === 'checkbox') {
      setFormData(prev => {
        const currentValues = prev[name] || [];
        if (checked) {
          return { ...prev, [name]: [...currentValues, value] };
        } else {
          return { 
            ...prev, 
            [name]: currentValues.filter(item => item !== value) 
          };
        }
      });
    } else {
      // Handle regular inputs
      setFormData(prev => ({
        ...prev,
        [name]: value
      }));
    }

    // Clear any existing errors
    setErrors(prev => ({ ...prev, [name]: '' }));
  };

  // Form Validation
  const validateForm = () => {
    const newErrors = {};

    if (!formData.age_group) 
      newErrors.age_group = 'Age group is required';
    if (!formData.gender) 
      newErrors.gender = 'Gender is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Form Submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitError('');
    
    // Validate form
    if (!validateForm()) return;

    // Get user from localStorage
    const user = JSON.parse(localStorage.getItem('user'));
    if (!user) {
      setSubmitError('User not found. Please log in again.');
      return;
    }

    setIsSubmitting(true);

    try {
      // Get CSRF token
      const csrfToken = getCsrfToken();

      const response = await fetch(`${API_BASE_URL}/api/health-assessment/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRFToken': csrfToken,
        },
        credentials: 'include',
        body: JSON.stringify({
          user_id: user.user_id,
          ...formData
        })
      });

      // Detailed error handling
      if (!response.ok) {
        const errorText = await response.text();
        console.error('Submission error:', {
          status: response.status,
          error: errorText
        });
        setSubmitError('Failed to submit health assessment');
        return;
      }

      const data = await response.json();
      
      // Update localStorage with health assessment status
      const updatedUser = {
        ...user,
        has_health_assessment: true
      };
      localStorage.setItem('user', JSON.stringify(updatedUser));

      // Navigate to dashboard
      navigate('/dashboard');

    } catch (error) {
      console.error('Health Assessment submission error:', error);
      setSubmitError('Network error. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="health-assessment-container">
      <h2>Health Assessment</h2>
      
      {submitError && (
        <div className="error-message">{submitError}</div>
      )}

      <form onSubmit={handleSubmit}>
        {/* Age Group */}
        <div className="form-group">
          <label>Age Group</label>
          <select 
            name="age_group"
            value={formData.age_group}
            onChange={handleChange}
          >
            <option value="">Select Age Group</option>
            {ageGroups.map(group => (
              <option key={group} value={group}>{group}</option>
            ))}
          </select>
          {errors.age_group && <span className="error">{errors.age_group}</span>}
        </div>

        {/* Gender */}
        <div className="form-group">
          <label>Gender</label>
          <select 
            name="gender"
            value={formData.gender}
            onChange={handleChange}
          >
            <option value="">Select Gender</option>
            <option value="Male">Male</option>
            <option value="Female">Female</option>
            <option value="Other">Other</option>
          </select>
          {errors.gender && <span className="error">{errors.gender}</span>}
        </div>

        {/* Respiratory Conditions */}
        <div className="form-group">
          <label>Respiratory Conditions</label>
          {respiratoryConditions.map(condition => (
            <label key={condition}>
              <input 
                type="checkbox"
                name="respiratory_conditions"
                value={condition}
                checked={formData.respiratory_conditions.includes(condition)}
                onChange={handleChange}
              />
              {condition}
            </label>
          ))}
        </div>

        {/* Smoking History */}
        <div className="form-group">
          <label>Smoking History</label>
          <select 
            name="smoking_history"
            value={formData.smoking_history}
            onChange={handleChange}
          >
            <option value="">Select Smoking History</option>
            <option value="Never smoker">Never smoker</option>
            <option value="Current smoker">Current smoker</option>
            <option value="Former smoker">Former smoker</option>
          </select>
        </div>

        {/* Other fields similarly structured */}
        
        <button 
          type="submit" 
          disabled={isSubmitting}
        >
          {isSubmitting ? 'Submitting...' : 'Submit Assessment'}
        </button>
      </form>
    </div>
  );
}

export default HealthAssessment;
